parameters.jsCode:
const item = $input.item.json;
const subject = item.subject || '';
const fromRaw = item.from || '';

const refMatch = subject.match(/\[REF-([A-Z0-9-]+)\]/i);
const ref = refMatch ? 'REF-' + refMatch[1].toUpperCase() : null;

const emailMatch = fromRaw.match(/<([^>]+)>/) || fromRaw.match(/([\w.-]+@[\w.-]+\.[a-z]+)/);
const fromEmail = emailMatch ? emailMatch[1] : fromRaw;

const attachments = item.attachments || item.att || [];
const cvAttachments = attachments
  .filter(att => {
    const name = (att.name || att.filename || '').toLowerCase();
    return name.endsWith('.pdf') || name.endsWith('.doc') || name.endsWith('.docx');
  })
  .map(att => ({
    filename: att.name || att.filename || 'cv.pdf',
    mimeType: att.mimeType || att.contentType || 'application/pdf',
    size: att.size || 0
  }));

const esc = (s) => String(s || '').replace(/'/g, "''");
const selectQuery = ref
  ? "SELECT m.id, m.ref, m.poste, m.lieu, m.secteur, m.mission, m.description_offre, m.profil_requis, m.date_fin_collecte, m.statut, m.drive_folder_id, c.nom AS client_nom FROM mandats m JOIN clients c ON c.id = m.client_id WHERE m.ref = '" + esc(ref) + "' LIMIT 1"
  : null;

return [{
  json: {
    subject_original: subject,
    sender_email: fromEmail,
    mandat_ref: ref,
    ref_found: ref !== null,
    cv_count: cvAttachments.length,
    cv_attachments: cvAttachments,
    email_date: item.date || '',
    select_query: selectQuery
  },
  binary: $input.item.binary
}];

const allItems = $input.all();
if (allItems.length === 0) {
  return [{ json: { mandat_found: false, mandat_active: false } }];
}
const mandatData = allItems[0].json;
if (!mandatData || !mandatData.id) {
  return [{ json: { mandat_found: false, mandat_active: false } }];
}
const emailData = $node['Extraire référence mandat'].json;

const binaryData = $node['Email Trigger (IMAP)'].binary || {};
const binaryKeys = Object.keys(binaryData);
const cvKeys = binaryKeys.filter(k => {
  const mime = binaryData[k].mimeType || '';
  const fname = (binaryData[k].fileName || binaryData[k].filename || '').toLowerCase();
  return mime.includes('pdf') || mime.includes('word') ||
         fname.endsWith('.pdf') || fname.endsWith('.doc') || fname.endsWith('.docx');
});

const now = new Date();
const dateFin = mandatData.date_fin_collecte ? new Date(mandatData.date_fin_collecte) : null;
const isActive = mandatData.statut === 'actif';
const isOpen = dateFin ? now <= dateFin : true;

return [{
  json: {
    mandat_found: true,
    mandat_active: isActive && isOpen,
    mandat_id: mandatData.id,
    mandat_ref: mandatData.ref,
    poste: mandatData.poste,
    lieu: mandatData.lieu,
    secteur: mandatData.secteur,
    mission: mandatData.mission,
    description_offre: mandatData.description_offre,
    profil_requis: mandatData.profil_requis,
    drive_folder_id: mandatData.drive_folder_id,
    client_nom: mandatData.client_nom,
    sender_email: emailData.sender_email,
    subject_original: emailData.subject_original,
    cv_count: cvKeys.length,
    cv_binary_key: cvKeys[0] || null,
    email_date: emailData.email_date
  },
  binary: $node['Email Trigger (IMAP)'].binary
}];

const extracted = $node['Information Extractor'].json.output;
const fusionData = $node['Fusionner email + mandat'].json;

const escapeSql = (str) => String(str || '').replace(/'/g, "''");
const escapeJson = (arr) => JSON.stringify(arr || []).replace(/'/g, "''");

const scoreResponse = $input.all()[0].json;
const analysisText = scoreResponse.choices?.[0]?.message?.content || '';

let scoring = {};
try {
  const cleaned = analysisText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  scoring = JSON.parse(cleaned);
} catch(e) {
  scoring = {
    score: 0,
    score_justification: 'Erreur parsing scoring',
    points_forts: [],
    points_faibles: [],
    recommendation: 'A_ETUDIER'
  };
}

const score = Math.min(100, Math.max(0, parseFloat(scoring.score) || 0));

const genreRaw = String(extracted.genre || '').trim();
let genre = 'Inconnu';
if (['M', 'm', 'Masculin', 'masculin', 'Male', 'male', 'Homme', 'homme'].includes(genreRaw)) {
  genre = 'M';
} else if (['F', 'f', 'Féminin', 'feminin', 'Féminine', 'Female', 'female', 'Femme', 'femme'].includes(genreRaw)) {
  genre = 'F';
}

return [{
  json: {
    mandat_id: fusionData.mandat_id,
    mandat_ref: fusionData.mandat_ref,
    drive_folder_id: fusionData.drive_folder_id,
    sender_email: fusionData.sender_email,
    poste: fusionData.poste,
    nom: escapeSql(extracted.nom || ''),
    prenom: escapeSql(extracted.prenom || ''),
    email_candidat: String(extracted.email || fusionData.sender_email || ''),
    telephone: String(extracted.telephone || ''),
    nationalite: escapeSql(extracted.nationalite || ''),
    genre: genre,
    annees_experience: Number(extracted.annees_experience || 0),
    niveau_formation: escapeSql(extracted.niveau_formation || ''),
    domaine_formation: escapeSql(extracted.domaine_formation || ''),
    dernier_poste: escapeSql(extracted.dernier_poste || ''),
    secteurs_exp: escapeJson(extracted.secteurs_exp || []),
    certifications: escapeJson(extracted.certifications || []),
    langues: escapeJson(extracted.langues || []),
    competences_cles: escapeJson(extracted.competences_cles || []),
    points_forts: escapeJson(scoring.points_forts || []),
    points_faibles: escapeJson(scoring.points_faibles || []),
    score: score,
    score_justification: escapeSql(scoring.score_justification || ''),
    recommendation: String(scoring.recommendation || 'A_ETUDIER')
  },
  binary: $node['Email Trigger (IMAP)'].binary
}];

