const extracted = $node['Information Extractor'].json.output;
const fusionData = $node['Fusionner email + mandat'].json;

const nom = (extracted.nom || '').replace(/"/g, '');
const prenom = (extracted.prenom || '').replace(/"/g, '');
const dernier_poste = (extracted.dernier_poste || '').replace(/"/g, '');
const annees_exp = extracted.annees_experience || 0;
const formation = ((extracted.niveau_formation || '') + ' ' + (extracted.domaine_formation || '')).replace(/"/g, '');
const secteurs = (extracted.secteurs_exp || []).join(', ').replace(/"/g, '');
const competences = (extracted.competences_cles || []).join(', ').replace(/"/g, '');
const poste = (fusionData.poste || '').replace(/"/g, '');
const secteur = (fusionData.secteur || '').replace(/"/g, '');
const profil = (fusionData.profil_requis || '').replace(/"/g, '');

const prompt = "Analyse ce profil candidat et evalue sa correspondance avec la fiche de poste. " +
  "PROFIL : Nom : " + nom + " " + prenom + ". " +
  "Dernier poste : " + dernier_poste + ". " +
  "Experience : " + annees_exp + " ans. " +
  "Formation : " + formation + ". " +
  "Secteurs : " + secteurs + ". " +
  "Competences : " + competences + ". " +
  "FICHE DE POSTE : Poste : " + poste + ". " +
  "Secteur : " + secteur + ". " +
  "Profil requis : " + profil + ". " +
  "SCORING SUR 100 POINTS STRICT : " +
"Experiences similaires ou transposables 40pts, " +
"Formation et diplomes pertinents 20pts, " +
"Competences techniques requises 20pts, " +
"Soft skills 10pts, " +
"Adequation geographique 10pts. " +
"REGLES ABSOLUES : " +
"Score 75-100 ET experience directe dans le secteur = A_RETENIR. " +
"Score 40-74 = A_ETUDIER. " +
"Score 0-39 = NON_RETENU. " +
"Ne jamais donner 100/100 sauf correspondance parfaite sur TOUS les criteres. " +
"Penaliser absence de competences cles. " +
  "Reponds UNIQUEMENT avec un objet JSON valide contenant : " +
  "score (nombre entier), " +
  "score_justification (texte factuel), " +
  "points_forts (tableau de 4 elements max), " +
  "points_faibles (tableau de 4 elements max), " +
  "recommendation (A_RETENIR ou A_ETUDIER ou NON_RETENU).";

return [{
  json: {
    prompt: prompt,
    mandat_id: fusionData.mandat_id,
    mandat_ref: fusionData.mandat_ref,
    drive_folder_id: fusionData.drive_folder_id,
    sender_email: fusionData.sender_email,
    poste: fusionData.poste
  },
  binary: $node['Email Trigger (IMAP)'].binary
}];

const data = $node['Formatter candidature'].json;
const drive = $input.all()[0].json;

const esc = (s) => String(s || '').replace(/'/g, "''");

const q = "INSERT INTO candidatures (mandat_id, nom, prenom, email, telephone, nationalite, genre, annees_experience, niveau_formation, domaine_formation, dernier_poste, secteurs_exp, certifications, langues, competences_cles, points_forts, points_faibles, score, score_justification, recommendation, cv_url, statut, created_at) VALUES (" +
  data.mandat_id + ", '" +
  data.nom + "', '" +
  data.prenom + "', '" +
  esc(data.email_candidat) + "', '" +
  esc(data.telephone) + "', '" +
  data.nationalite + "', '" +
  data.genre + "', " +
  data.annees_experience + ", '" +
  data.niveau_formation + "', '" +
  data.domaine_formation + "', '" +
  data.dernier_poste + "', '" +
  data.secteurs_exp + "'::jsonb, '" +
  data.certifications + "'::jsonb, '" +
  data.langues + "'::jsonb, '" +
  data.competences_cles + "'::jsonb, '" +
  data.points_forts + "'::jsonb, '" +
  data.points_faibles + "'::jsonb, " +
  data.score + ", '" +
  data.score_justification + "', '" +
  data.recommendation + "', '" +
  esc(drive.webViewLink || '') + "', 'recu', NOW()) RETURNING id";

return [{
  json: {
    insert_query: q
  }
}];
